def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(_io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(_io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _fmt(v, nd=4):
    if v is None:
        return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return v
    if np.isnan(f) or np.isinf(f):
        return None
    return round(f, nd)


def _style(ax):
    for s in ('top', 'right'):
        ax.spines[s].set_visible(False)
    ax.spines['left'].set_color('#333333')
    ax.spines['bottom'].set_color('#333333')
    ax.grid(True, axis='y', linestyle='--', linewidth=0.5, color='#CCCCCC', alpha=0.5)
    ax.set_axisbelow(True)
    ax.tick_params(labelsize=9, colors='#555555')


def _png(fig):
    _buf = _io.BytesIO()
    fig.savefig(_buf, format='png', dpi=300, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    return 'data:image/png;base64,' + base64.b64encode(_buf.getvalue()).decode('ascii')


def _clean_series(df, col):
    """数值化 + 缺失值线性插值，返回 (Series, 缺失数)"""
    s = pd.to_numeric(df[col], errors='coerce').astype(float)
    n_miss = int(s.isna().sum())
    if n_miss:
        s = s.interpolate(method='linear', limit_direction='both').ffill().bfill()
    return s, n_miss


def _x_axis(df, time_column):
    """x 轴：时间列（解析成功率高时）或序号。返回 (x, 是否时间)"""
    if time_column and time_column in df.columns:
        dt = pd.to_datetime(df[time_column], errors='coerce')
        if dt.notna().sum() >= max(2, int(len(dt) * 0.9)):
            return dt, True
    return np.arange(len(df)), False


def _check_col(df, col, name):
    if not col:
        raise RuntimeError('请选择' + name)
    if col not in df.columns:
        raise RuntimeError(name + '「' + str(col) + '」不存在，可选列：' + str(list(df.columns)))


# ───────────── 智能列识别 ─────────────

def _is_idlike(df, col):
    cl = str(col).lower()
    if _re.search(r'\b(id|code|sku|no)\b', cl) or any(k in cl for k in ('编码', '编号', '序号', '单号', '条码')):
        return True
    s = df[col].dropna()
    if len(s) == 0:
        return True
    num = pd.to_numeric(s, errors='coerce')
    if num.notna().sum() >= max(2, int(len(s) * 0.9)):
        # 数值列：只有"整数编码"且唯一值极高才判为 ID（如单品编码）；连续小数不算
        intlike = bool((num.dropna() % 1 == 0).all())
        return intlike and len(s) > 10 and s.nunique() / float(len(s)) > 0.95
    # 非数值列：唯一值比例极高视为 ID（但能解析为日期/时间的列除外）
    dt = pd.to_datetime(s, errors='coerce')
    if dt.notna().sum() >= max(2, int(len(s) * 0.9)):
        return False
    return len(s) > 10 and s.nunique() / float(len(s)) > 0.95


def _auto_time_columns(df, exclude=()):
    """找出能解析为时间（datetime 成功率≥90%）的列，排除 ID 类与普通整数列"""
    out = []
    for c in df.columns:
        if c in exclude or _is_idlike(df, c):
            continue
        raw = df[c].dropna()
        if len(raw) < 2:
            continue
        num = pd.to_numeric(raw, errors='coerce')
        if num.notna().sum() >= max(2, int(len(raw) * 0.9)):
            # 纯数值列：仅当像 YYYYMMDD 的 8 位整数日期（18000101~22000101）才视为时间
            intlike = bool((num.dropna() % 1 == 0).all())
            if not intlike:
                continue
            nums = num.dropna().astype('int64')
            if not ((nums >= 18000101) & (nums <= 22000101)).all():
                continue
        dt = pd.to_datetime(raw, errors='coerce')
        if dt.notna().sum() >= max(2, int(len(raw) * 0.9)):
            out.append(c)
    return out


def _auto_num_columns(df, exclude=()):
    """找出数值化成功率≥80% 且非时间/非ID 的列（候选数值列）"""
    out = []
    for c in df.columns:
        if c in exclude or _is_idlike(df, c):
            continue
        num = pd.to_numeric(df[c], errors='coerce')
        if num.notna().sum() >= max(2, int(len(df) * 0.8)):
            out.append(c)
    return out


def _pick_default_numeric(df, cands):
    """从候选数值列里挑信息量最大的：非缺失数 × 标准差，含"销量/数量/值"等语义关键词的列优先"""
    _SEM_KEYWORDS = ('销量', '销售量', '数量', '需求', '产量', '值', '价', 'value', 'amount', 'price', 'quantity')
    best, best_score = None, -1.0
    for c in cands:
        num = pd.to_numeric(df[c], errors='coerce')
        sd = float(num.std(ddof=1)) if num.notna().sum() > 1 else 0.0
        score = float(num.notna().sum()) * (sd if sd > 0 else 1.0)
        cl = str(c).lower()
        if any(k in cl for k in _SEM_KEYWORDS):
            score *= 1.5
        if score > best_score:
            best, best_score = c, score
    return best


def _auto_group_columns(df, exclude=()):
    """找出类别列：非ID、类别数适中（2~30）；低基数的整数列（如月份1-12）也算类别"""
    out = []
    for c in df.columns:
        if c in exclude or _is_idlike(df, c):
            continue
        s = df[c].dropna()
        if len(s) < 2:
            continue
        nuniq = s.nunique()
        if not (2 <= nuniq <= 30):
            continue
        num = pd.to_numeric(s, errors='coerce')
        num_ok = num.notna().sum() >= max(2, int(len(s) * 0.9))
        if num_ok:
            # 数值列仅当为整数（低基数类别如 1~12 月）时才视作类别列；连续小数不算
            if not bool((num.dropna() % 1 == 0).all()):
                continue
        out.append(c)
    return out


# ───────────── 时间分段 ─────────────
_SEG_OPTIONS = ('不分段', '自动分段', '按年', '按季度', '按月', '按周', '按天')
_SEG_PICK_OPTIONS = ('全部',) + tuple('第{}段'.format(i) for i in range(1, 13))


def _seg_granularity(dt_series, mode):
    """自动选粒度：让段数落在合理范围——排除少于2段（太粗无意义）或超过12段（太碎、图上放不下），
    取段数最接近 8 的粒度；平手取更粗（画面更清爽）。
    例：3年→按季度12段、1年→按季度4段、8个月→按月8段、45天→按周6段、10天→按天、30天→按周(自动不会选按天30段)"""
    if mode != '自动分段':
        return mode
    s = pd.Series(list(dt_series.dropna()))
    if len(s) < 2:
        return '按天'
    cands = ('按年', '按季度', '按月', '按周', '按天')
    best, best_score = None, None
    for m in cands:
        n_seg = len({_seg_key(t, m) for t in s})
        if n_seg < 2 or n_seg > 12:
            continue  # 段数太少没意义；太多会糊（如 1085 天按天 1085 段）
        score = abs(n_seg - 8)
        if best_score is None or score < best_score or (score == best_score and cands.index(m) < cands.index(best)):
            best, best_score = m, score
    return best if best is not None else '按年'  # 兜底：所有粒度都超界时取最粗


def _time_resolution(xdt):
    """数据时间分辨率：判断一天内是否有多条记录（小时/分钟级）"""
    diffs = pd.Series(xdt.dropna().sort_values()).diff().dropna()
    if len(diffs) == 0:
        return None
    med = diffs.median()
    if med < pd.Timedelta(minutes=1):
        return '秒级（一分钟内多条）'
    if med < pd.Timedelta(hours=1):
        return '分钟级（一天内多条）'
    if med < pd.Timedelta(days=1):
        return '小时级（一天内多条）'
    if med < pd.Timedelta(days=2):
        return '天级（每天约1条）'
    if med < pd.Timedelta(days=8):
        return '周级'
    return '月级或更粗'


def _seg_key(t, mode):
    """单个时间点 → 所属段标签"""
    if mode == '按年':
        return str(t.year) + '年'
    if mode == '按季度':
        return str(t.year) + '年Q' + str((t.month - 1) // 3 + 1)
    if mode == '按月':
        return t.strftime('%Y-%m')
    if mode == '按周':
        return t.strftime('%Y') + '年W' + str(t.isocalendar()[1]).zfill(2)
    return t.strftime('%Y-%m-%d')


def _segments(dt_series, mode):
    """返回 [(起点idx, 终点idx, 段标签), ...]（按连续同标签切块）"""
    keys = [_seg_key(t, mode) for t in dt_series]
    out, start, cur = [], 0, keys[0]
    for i in range(1, len(keys) + 1):
        if i == len(keys) or keys[i] != cur:
            out.append((start, i - 1, cur))
            if i < len(keys):
                start, cur = i, keys[i]
    return out


def _sig(p):
    return '*' if p < 0.05 else ''


if data is None:
    raise RuntimeError('请先连接并运行上游的数据导入插件')
df = _to_frame(data)

report = {'检验方法': method, '数值列': value_column}
image = None

# ═══════════════ 1. 时序图 ═══════════════
if method == '时序图':
    # ── 智能列识别：数值列/时间列留空时由插件自动判断 ──
    time_cands = _auto_time_columns(df)
    num_cands = _auto_num_columns(df, exclude=time_cands)
    if not value_column:
        value_column = _pick_default_numeric(df, num_cands)
        if value_column is None:
            raise RuntimeError('未找到可用的数值列（请检查数据是否为数值型，或手动指定数值列）')
    if not time_column:
        time_column = time_cands[0] if time_cands else ''
    _check_col(df, value_column, '数值列')
    s, n_miss = _clean_series(df, value_column)
    x, is_time = _x_axis(df, time_column)
    arr = s.to_numpy()
    n = len(arr)
    if n < 3:
        raise RuntimeError('清洗后有效样本不足 3 个')
    # ── 大数据自动聚合降采样（>4000 点时按 天→周→月 聚合均值，保持画面清爽）──
    agg_note = None
    if is_time and n > 4000:
        _xdt = pd.to_datetime(x, errors='coerce')
        if _xdt.notna().sum() >= int(n * 0.9):
            _tmp = pd.DataFrame({'t': _xdt, 'v': arr}).dropna()
            for _rule, _rname in (('D', '天'), ('W', '周'), ('M', '月')):
                _g = _tmp.set_index('t').resample(_rule).mean().dropna()
                if len(_g) <= 4000 or _rule == 'M':
                    x = pd.Series(_g.index)
                    arr = _g['v'].to_numpy()
                    n = len(arr)
                    agg_note = '按{}聚合显示（{}→{}点）'.format(_rname, int(len(_tmp)), n)
                    break
    # ── 数据时间分辨率（识别"一天内多条记录"等情形）──
    time_res = None
    if is_time:
        _rdt = pd.to_datetime(x, errors='coerce')
        if _rdt.notna().sum() >= max(2, int(n * 0.9)):
            time_res = _time_resolution(_rdt)
    # ── 时间分段：按文件内容自动划分时间段（仅时间轴有效）──
    segs = None
    seg_gran = segment_mode if segment_mode in _SEG_OPTIONS else '不分段'
    if is_time and seg_gran != '不分段' and n >= 4:
        xdt = pd.to_datetime(x, errors='coerce')
        if xdt.notna().sum() >= int(n * 0.9):
            gran = _seg_granularity(xdt.dropna(), seg_gran)
            segs = _segments(xdt, gran)
            if len(segs) < 2:
                segs = None  # 只有一个段就退化为不分段
    # ── 段选择：下拉直接选第几段（无需输入日期）──
    seg_pick = segment_index if segment_index in _SEG_PICK_OPTIONS else '全部'
    range_label = '全区间'
    if segs is not None and len(segs) > 1 and seg_pick != '全部':
        seg_no = int(seg_pick.replace('第', '').replace('段', ''))
        if seg_no > len(segs):
            raise RuntimeError('该数据按「' + gran + '」只分成 ' + str(len(segs))
                               + ' 段，没有第 ' + str(seg_no) + ' 段，请在下拉中重新选择')
        a, b, lab = segs[seg_no - 1]
        x = x[a:b + 1]
        arr = arr[a:b + 1]
        n = len(arr)
        range_label = '第{}段（{}）'.format(seg_no, lab)
        segs = None  # 只看单段，不再叠加分段色带
    mean = float(arr.mean())
    sd = float(arr.std(ddof=1))
    ma = None
    win = smooth_window
    if win > 1 and n > 2:
        win = min(win, n)
        ma = pd.Series(arr).rolling(win, center=True, min_periods=1).mean().to_numpy()
    fig, ax = plt.subplots(figsize=(9, 4.6))
    if n <= 120:
        ax.plot(x, arr, color=NAVY, linewidth=2.0, marker='o', markersize=3, zorder=3)
    else:
        ax.plot(x, arr, color=NAVY, linewidth=1.8, zorder=3)
    ax.axhline(mean, color=BROWN, linestyle='--', linewidth=1.2, alpha=0.9,
               label='均值 = {:.4g}'.format(mean))
    if ma is not None:
        ax.plot(x, ma, color=GOLD, linewidth=1.8, label='移动平均（窗口{}）'.format(win))
    ax.set_title('时序图：{}{}'.format(value_column, ('（' + range_label + '）' if range_label != '全区间' else '')),
                 fontsize=14, fontweight='bold', pad=10)
    ax.set_xlabel('时间' if is_time else '序号 t', fontsize=11, color='#333333')
    ax.set_ylabel(value_column, fontsize=11, color='#333333')
    ax.legend(frameon=False, fontsize=9, loc='best')
    if segs is not None and len(segs) > 1:
        ymin, ymax = ax.get_ylim()
        pad = (ymax - ymin) * 0.07
        n_seg = len(segs)
        if n_seg <= 12:
            # 段数适中：画淡色带 + 段名 + 分界虚线
            ax.set_ylim(ymin, ymax + pad * 2.2)
            lab_y = ymax + pad * 1.4
            for i, (a, b, lab) in enumerate(segs):
                xa, xb = x.iloc[a], x.iloc[b]
                if i % 2 == 0:
                    ax.axvspan(xa, xb, color=NAVY, alpha=0.028, zorder=0)
                if i > 0:
                    ax.axvline(xa, color='#AAAAAA', linestyle=':', linewidth=0.7, zorder=2)
                ax.text(xa + (xb - xa) / 2, lab_y, lab, ha='center', va='bottom',
                        fontsize=8, color='#666666')
            ax.text(x.iloc[0], lab_y + pad * 1.0, '按「' + gran + '」分 {} 段（可下拉选段查看）'.format(n_seg),
                    ha='left', va='bottom', fontsize=8.5, color=RED)
        else:
            # 段数过多（如按天切出上百段）：省略色带/段名/竖线，保持画面干净
            ax.set_ylim(ymin, ymax + pad * 1.4)
            ax.text(x.iloc[0], ymax + pad * 0.6,
                    '共 {} 段（段数较多，标注已省略；可在「查看时间段」下拉逐段查看）'.format(n_seg),
                    ha='left', va='bottom', fontsize=8.5, color=RED)
    _style(ax)
    if is_time:
        plt.setp(ax.get_xticklabels(), rotation=30, ha='right')
    k = max(1, int(n * 0.2))
    m_head, m_tail = float(arr[:k].mean()), float(arr[-k:].mean())
    delta = m_tail - m_head
    trend = '上升' if delta > 0.05 * sd else ('下降' if delta < -0.05 * sd else '平稳')
    report.update({'列识别_时间列候选': ('、'.join(map(str, time_cands)) if time_cands else '未识别到'),
                   '列识别_数值列候选': ('、'.join(map(str, num_cands)) if num_cands else '未识别到'),
                   '列识别_已用数值列': str(value_column),
                   '列识别_已用时间列': (str(time_column) if time_column else '（未用，x轴按序号）')})
    if agg_note:
        report['显示方式'] = agg_note
    if time_res:
        report['时间分辨率'] = time_res
    if segs is not None and len(segs) > 1:
        n_seg = len(segs)
        report.update({'分段模式': gran, '分段数': int(n_seg)})
        MAX_SEG_REPORT = 40
        seg_means = []
        listed = segs if n_seg <= MAX_SEG_REPORT else segs[:MAX_SEG_REPORT]
        for i, (a, b, lab) in enumerate(listed, 1):
            seg_arr = arr[a:b + 1]
            seg_mean = float(seg_arr.mean())
            seg_sd = float(seg_arr.std(ddof=1)) if len(seg_arr) > 1 else 0.0
            seg_means.append(seg_arr)
            report.update({
                '段' + str(i) + '_区间': lab,
                '段' + str(i) + '_样本量': int(len(seg_arr)),
                '段' + str(i) + '_均值': _fmt(seg_mean),
                '段' + str(i) + '_标准差': _fmt(seg_sd),
                '段' + str(i) + '_首尾差': _fmt(float(seg_arr[-1] - seg_arr[0])),
            })
        if n_seg > MAX_SEG_REPORT:
            report['段统计_提示'] = '段数过多，报告仅列出前 {} 段；可在「查看时间段」下拉中逐段查看'.format(MAX_SEG_REPORT)
        if 2 <= n_seg <= 30:
            f_res = stats.f_oneway(*seg_means)
            seg_f, seg_p = float(f_res.statistic), float(f_res.pvalue)
            report['段间ANOVA_F统计量'] = _fmt(seg_f)
            report['段间ANOVA_p值'] = _fmt(seg_p, 6)
        elif n_seg > 30:
            report['段间ANOVA_提示'] = '段数过多（{} 段），省略段间ANOVA检验'.format(n_seg)
    report.update({
        '样本量': int(n),
        '时间区间': range_label,
        '均值': _fmt(mean), '标准差': _fmt(sd),
        '最小值': _fmt(float(arr.min())), '最大值': _fmt(float(arr.max())),
        '缺失值插值数': int(n_miss),
        '前20%均值': _fmt(m_head), '后20%均值': _fmt(m_tail),
        '趋势方向': trend, '首尾均值差Δ': _fmt(delta),
        '结论': ('时序图显示「' + str(value_column) + '」在观测期内整体呈' + trend + '趋势（前20%均值='
                + '{:.4g}，后20%均值={:.4g}，Δ={:+.4g}）。'.format(m_head, m_tail, delta)
                + ('移动平均线（窗口{}）进一步平滑了短期波动，便于观察长期趋势。'.format(win) if ma is not None else '')
                + (('数据为' + str(time_res) + '，已识别并在分段时考虑。' if time_res and '多条' in str(time_res) else ''))
                + (('序列按「' + gran + '」划分为 ' + str(len(segs)) + ' 段（各段统计见报告）；段间均值差异 '
                    + ('显著' if seg_p < alpha else '不显著')
                    + '（ANOVA F=' + '{:.3f}'.format(seg_f) + '，p=' + '{:.2e}'.format(seg_p) + '）。'
                    if segs is not None and len(segs) > 1 and len(segs) <= 30
                    else (('序列按「' + gran + '」划分为 ' + str(len(segs)) + ' 段（段数较多，各段统计见报告）。'
                           if segs is not None and len(segs) > 30 else ''))))),
    })
    image = _png(fig)

# ═══════════════ 2. 分组统计 ═══════════════
elif method == '分组统计':
    # ── 智能列识别：数值列/分组列留空时自动判断 ──
    _num_cands = _auto_num_columns(df)
    _time_cands = _auto_time_columns(df)
    _group_cands = _auto_group_columns(df, exclude=_time_cands)  # 只排除时间列（低基数整数列仍可作分组列）
    if not group_column:
        group_column = _group_cands[0] if _group_cands else ''
    if not value_column:
        value_column = _pick_default_numeric(df, _num_cands)
        if value_column is None:
            raise RuntimeError('未找到可用的数值列（请检查数据是否为数值型，或手动指定数值列）')
    _check_col(df, group_column, '分组列')
    _check_col(df, value_column, '数值列')
    if group_column == value_column:
        raise RuntimeError('分组列和数值列不能是同一个列，请重新选择（分组列选类别列，数值列选被检验的数值列）')
    sub = df[[group_column, value_column]].dropna()
    if len(sub) == 0:
        raise RuntimeError('分组列与数值列没有同时非缺失的行')
    groups = {}
    for label, g in sub.groupby(group_column, sort=True):
        arr = pd.to_numeric(g[value_column], errors='coerce').dropna().to_numpy().astype(float)
        if len(arr) > 0:
            groups[str(label)] = arr
    if len(groups) < 2:
        raise RuntimeError('清洗非数字内容后有效分组不足 2 组（仅剩 ' + str(len(groups)) + ' 组）')
    keys = list(groups.keys())
    ns = [len(groups[k]) for k in keys]
    means = [float(groups[k].mean()) for k in keys]
    sds = [float(groups[k].std(ddof=1)) for k in keys]
    if errorbar_type == '标准差SD':
        errs = list(sds)
    elif errorbar_type == '标准误SEM':
        errs = [sd / np.sqrt(m) for sd, m in zip(sds, ns)]
    elif errorbar_type == '95%置信区间':
        errs = [stats.t.ppf(0.975, max(m - 1, 1)) * sd / np.sqrt(m) for sd, m in zip(sds, ns)]
    else:
        errs = [0.0] * len(keys)
    ymax = max(m + e for m, e in zip(means, errs))
    fig, ax = plt.subplots(figsize=(max(6.5, 0.9 * len(keys) + 2.5), 5))
    xs = np.arange(len(keys))
    ax.bar(xs, means, width=0.65, color=NAVY, edgecolor='#333333', linewidth=0.8, alpha=0.9, zorder=3)
    if errorbar_type != '无':
        ax.errorbar(xs, means, yerr=errs, fmt='none', ecolor='#333333', capsize=4,
                    elinewidth=1.2, capthick=1.2, zorder=4)
    for i, (m, e) in enumerate(zip(means, errs)):
        ax.text(i, m + e + 0.05 * ymax, '{:.4g}'.format(m), ha='center', fontsize=9, color='#222222')
    f_res = stats.f_oneway(*[groups[k] for k in keys])
    f_stat, p_anova = float(f_res.statistic), float(f_res.pvalue)
    all_ = np.concatenate([groups[k] for k in keys])
    grand = float(all_.mean())
    ss_between = float(sum(len(groups[k]) * (float(groups[k].mean()) - grand) ** 2 for k in keys))
    ss_total = float(((all_ - grand) ** 2).sum())
    eta2 = ss_between / ss_total if ss_total > 0 else None
    ax.text(0.98, 0.96, 'ANOVA: F={:.3f}, p={:.2e}{}'.format(f_stat, p_anova, _sig(p_anova)),
            transform=ax.transAxes, ha='right', va='top', fontsize=10, color='#333333',
            bbox=dict(facecolor='white', edgecolor='#999999', alpha=0.9, boxstyle='round,pad=0.3'))
    ax.set_xticks(xs)
    ax.set_xticklabels([str(k) + '\nn=' + str(m) for k, m in zip(keys, ns)], fontsize=9)
    ax.set_ylim(0, ymax * 1.22)
    ax.set_title('分组统计：按「{}」分组（{}）'.format(group_column, value_column), fontsize=14, fontweight='bold', pad=10)
    ax.set_ylabel(value_column, fontsize=11, color='#333333')
    _style(ax)
    report.update({'分组列': group_column, '组数': int(len(keys)), '样本量_总': int(len(all_)),
                   '列识别_分组列候选': ('、'.join(map(str, _group_cands)) if _group_cands else '未识别到'),
                   '列识别_数值列候选': ('、'.join(map(str, _num_cands)) if _num_cands else '未识别到')})
    for i, (k, g) in enumerate(zip(keys, [groups[k] for k in keys]), 1):
        report.update({
            '组' + str(i) + '_标签': k,
            '组' + str(i) + '_样本量': int(len(g)),
            '组' + str(i) + '_均值': _fmt(float(g.mean())),
            '组' + str(i) + '_标准差': _fmt(float(g.std(ddof=1))),
            '组' + str(i) + '_最小值': _fmt(float(g.min())),
            '组' + str(i) + '_最大值': _fmt(float(g.max())),
        })
    if p_anova < alpha:
        anova_concl = '小于显著性水平 α=' + str(alpha) + '，组间均值差异显著，提示该分组维度蕴含系统性差异（如季节/周期成分）'
    else:
        anova_concl = '不小于显著性水平 α=' + str(alpha) + '，组间均值差异不显著，该分组维度对' + str(value_column) + '无明显影响'
    report.update({
        'ANOVA_F统计量': _fmt(f_stat), 'ANOVA_p值': _fmt(p_anova, 6),
        'ANOVA_效应量η²': _fmt(eta2), '误差棒类型': errorbar_type,
        '结论': ('按「' + str(group_column) + '」分组的「' + str(value_column) + '」均值差异 ANOVA F=' + '{:.3f}'.format(f_stat)
                + '，p=' + '{:.2e}'.format(p_anova) + '，' + anova_concl + '。'),
    })
    image = _png(fig)

# ═══════════════ 3. 自相关函数 ACF ═══════════════
elif method == '自相关函数ACF':
    from statsmodels.tsa.stattools import acf
    from statsmodels.stats.diagnostic import acorr_ljungbox
    # ── 智能列识别：数值列留空时自动判断 ──
    _time_cands = _auto_time_columns(df)
    _num_cands = _auto_num_columns(df, exclude=_time_cands)
    if not value_column:
        value_column = _pick_default_numeric(df, _num_cands)
        if value_column is None:
            raise RuntimeError('未找到可用的数值列（请检查数据是否为数值型，或手动指定数值列）')
    _check_col(df, value_column, '数值列')
    s, n_miss = _clean_series(df, value_column)
    arr = s.to_numpy()
    n = len(arr)
    if n < 4:
        raise RuntimeError('清洗后有效样本不足 4 个')
    lag = int(min(max_lag, n - 2))
    if lag < 1:
        raise RuntimeError('最大滞后阶数需 ≥ 1')
    a = acf(arr, nlags=lag)
    ci = 1.96 / np.sqrt(n)
    sig_lags = [k for k in range(1, len(a)) if abs(a[k]) > ci]
    peaks = []
    for k in range(1, len(a) - 1):
        if a[k] >= a[k - 1] and a[k] > a[k + 1] and abs(a[k]) > ci:
            peaks.append((k, float(a[k])))
    period_hint = None
    if peaks:
        k0, a0 = max(peaks, key=lambda t: abs(t[1]))
        mult = [m for m in (2 * k0, 3 * k0) if m < len(a) and abs(a[m]) > ci]
        if len(mult) >= 1:
            period_hint = k0
        elif len(peaks) >= 2:
            ks = [p[0] for p in peaks]
            if abs(ks[1] - ks[0]) == ks[0]:
                period_hint = ks[0]
        else:
            period_hint = None
    lb = acorr_ljungbox(arr, lags=[lag], return_df=True)
    lb_q = float(lb['lb_stat'].iloc[0])
    lb_p = float(lb['lb_pvalue'].iloc[0])
    slow = n > 10 and abs(a[1]) > 0.7
    white = len(sig_lags) == 0
    fig, ax = plt.subplots(figsize=(9, 4.6))
    colors = [NAVY if (k == 0 or abs(a[k]) > ci) else '#CCCCCC' for k in range(len(a))]
    ax.bar(np.arange(len(a)), a, width=0.8, color=colors, edgecolor='#FFFFFF', linewidth=0.5, zorder=3)
    ax.fill_between([-0.5, lag + 0.5], -ci, ci, color='#999999', alpha=0.15, zorder=1)
    ax.axhline(0, color='#333333', linewidth=0.8, zorder=2)
    ax.axhline(ci, color='#999999', linestyle='--', linewidth=0.8, zorder=2)
    ax.axhline(-ci, color='#999999', linestyle='--', linewidth=0.8, zorder=2)
    ax.text(lag, ci * 1.08, '95%置信界限 ±1.96/√n = ±{:.3f}'.format(ci),
            fontsize=8.5, ha='right', color='#555555')
    for k, av in sorted(peaks, key=lambda t: -abs(t[1]))[:3]:
        ax.text(k, av + 0.06, '{}'.format(k), ha='center', fontsize=8, color=RED)
    ax.set_title('自相关函数 ACF：{}'.format(value_column), fontsize=14, fontweight='bold', pad=10)
    ax.set_xlabel('滞后阶数 k', fontsize=11, color='#333333')
    ax.set_ylabel('自相关系数 r(k)', fontsize=11, color='#333333')
    ax.set_xlim(-0.5, lag + 0.5)
    _style(ax)
    report.update({'样本量': int(n), '最大滞后': int(lag), '缺失值插值数': int(n_miss),
                   '列识别_数值列候选': ('、'.join(map(str, _num_cands)) if _num_cands else '未识别到'),
                   '列识别_已用数值列': str(value_column),
                   '置信界限±1.96/√n': _fmt(ci), '显著滞后数': int(len(sig_lags)),
                   '显著滞后列表': '、'.join(str(k) for k in sig_lags[:30]) if sig_lags else '无',
                   '最强峰值_滞后': int(peaks[0][0]) if peaks else None,
                   '最强峰值_ACF值': _fmt(peaks[0][1]) if peaks else None,
                   '候选周期': int(period_hint) if period_hint else None,
                   'Ljung-Box_Q统计量': _fmt(lb_q), 'Ljung-Box_p值': _fmt(lb_p, 6)})
    for k in range(1, len(a)):
        report['ACF_滞后' + str(k)] = _fmt(a[k])
    if period_hint:
        acf_concl = ('ACF 在滞后 k=' + str(period_hint) + ' 及倍数处出现显著峰值（r='
                     + '{:.3f}'.format(a[period_hint]) + ' > ' + '{:.3f}'.format(ci)
                     + '），呈现周期衰减形态，提示序列存在周期约为 ' + str(period_hint) + ' 的周期性成分。')
    elif white:
        acf_concl = 'ACF 各滞后均落入 95% 置信界限内，序列近似白噪声，未检测到显著自相关或周期性。'
    elif slow:
        acf_concl = 'ACF 衰减缓慢（r(1)=' + '{:.3f}'.format(a[1]) + '），序列存在强趋势/非平稳特征，建议先差分或去趋势后再做周期检验。'
    else:
        acf_concl = 'ACF 快速衰减至置信界限内，序列呈平稳特征，未见规则周期峰值。'
    report.update({'自相关特征': ('周期衰减（候选周期 ' + str(period_hint) + '）' if period_hint else ('白噪声' if white else '非平稳慢衰减' if slow else '平稳无周期')),
                   '结论': acf_concl + (' Ljung-Box Q=' + '{:.2f}'.format(lb_q) + '（p=' + '{:.2e}'.format(lb_p) + '），序列存在显著自相关。' if lb_p < alpha else ' Ljung-Box 检验未拒绝白噪声假设。')})
    image = _png(fig)

# ═══════════════ 4. FFT / 功率谱分析 ═══════════════
elif method == 'FFT功率谱分析':
    from scipy.signal import find_peaks
    # ── 智能列识别：数值列留空时自动判断 ──
    _time_cands = _auto_time_columns(df)
    _num_cands = _auto_num_columns(df, exclude=_time_cands)
    if not value_column:
        value_column = _pick_default_numeric(df, _num_cands)
        if value_column is None:
            raise RuntimeError('未找到可用的数值列（请检查数据是否为数值型，或手动指定数值列）')
    _check_col(df, value_column, '数值列')
    if sampling_interval <= 0:
        raise RuntimeError('采样间隔必须 > 0')
    s, n_miss = _clean_series(df, value_column)
    arr = s.to_numpy()
    n = len(arr)
    if n < 8:
        raise RuntimeError('清洗后有效样本不足 8 个')
    y = arr - float(arr.mean())
    fft = np.fft.rfft(y)
    freq = np.fft.rfftfreq(n, d=sampling_interval)
    amp = np.abs(fft) * 2.0 / n
    amp[0] = 0.0
    power = (np.abs(fft) ** 2) / n
    power[0] = 0.0
    pk_idx, _ = find_peaks(amp, distance=max(1, int(n / 40)))
    pk_idx = [i for i in pk_idx if freq[i] > 0]
    pk_sorted = sorted(pk_idx, key=lambda i: amp[i], reverse=True)[:max(top_peaks, 1)]
    if not pk_sorted:
        raise RuntimeError('频谱中未检测到明显主峰（序列可能近似白噪声），建议改用 ACF 或 STL 方法')
    total_p = float(power[1:].sum()) or 1e-12
    fny = 0.5 / sampling_interval
    fig, axes = plt.subplots(2, 1, figsize=(10, 6.6), sharex=True)
    ax1, ax2 = axes
    ax1.plot(freq, amp, color=NAVY, linewidth=1.6, zorder=3)
    ax1.scatter([freq[i] for i in pk_sorted], [amp[i] for i in pk_sorted],
                color=RED, s=32, zorder=4, edgecolors='#333333', linewidth=0.4)
    for i in pk_sorted[:3]:
        ax1.annotate('T={:.2f}'.format(1.0 / freq[i]), xy=(freq[i], amp[i]),
                     xytext=(0, 8), textcoords='offset points', ha='center', fontsize=8.5, color=RED)
    ax1.set_title('FFT 幅值谱：{}'.format(value_column), fontsize=14, fontweight='bold', pad=10)
    ax1.set_ylabel('幅值', fontsize=11, color='#333333')
    _style(ax1)
    pdb = 10.0 * np.log10(power + 1e-12)
    ax2.plot(freq, pdb, color=GREEN, linewidth=1.4, zorder=3)
    ax2.axvline(fny, color=BROWN, linestyle=':', linewidth=0.8, zorder=2)
    ax2.set_xlabel('频率（单位：1/采样间隔 ' + '{:g}'.format(sampling_interval) + '）', fontsize=11, color='#333333')
    ax2.set_ylabel('功率谱密度 (dB)', fontsize=11, color='#333333')
    _style(ax2)
    plt.tight_layout()
    report.update({'样本量': int(n), '缺失值插值数': int(n_miss), '采样间隔': _fmt(sampling_interval),
                   '列识别_数值列候选': ('、'.join(map(str, _num_cands)) if _num_cands else '未识别到'),
                   '列识别_已用数值列': str(value_column),
                   '奈奎斯特频率': _fmt(fny), '主峰数': int(len(pk_sorted))})
    for rank, i in enumerate(pk_sorted, 1):
        report.update({
            '主峰' + str(rank) + '_频率': _fmt(freq[i], 6),
            '主峰' + str(rank) + '_周期': _fmt(1.0 / freq[i], 4),
            '主峰' + str(rank) + '_幅值': _fmt(amp[i]),
            '主峰' + str(rank) + '_功率占比%': _fmt(100.0 * power[i] / total_p, 2),
        })
    i0 = pk_sorted[0]
    pct0 = 100.0 * power[i0] / total_p
    if len(pk_sorted) >= 2:
        i1 = pk_sorted[1]
        fft_concl = ('功率谱显示最强周期成分 T=' + '{:.4g}'.format(1.0 / freq[i0])
                     + '（频率 f=' + '{:.4g}'.format(freq[i0]) + '，幅值 '
                     + '{:.4g}'.format(amp[i0]) + '，占非直流谱能量 {:.1f}%'.format(pct0)
                     + '），次强周期 T=' + '{:.4g}'.format(1.0 / freq[i1])
                     + '（幅值 ' + '{:.4g}'.format(amp[i1]) + '）。')
    else:
        fft_concl = ('功率谱显示最强周期成分 T=' + '{:.4g}'.format(1.0 / freq[i0])
                     + '（频率 f=' + '{:.4g}'.format(freq[i0]) + '，幅值 '
                     + '{:.4g}'.format(amp[i0]) + '，占非直流谱能量 {:.1f}%'.format(pct0) + '）。')
    report.update({'最强周期': _fmt(1.0 / freq[i0], 4), '最强周期_功率占比%': _fmt(pct0, 2), '结论': fft_concl})
    image = _png(fig)

# ═══════════════ 5. STL 季节分解 ═══════════════
elif method == 'STL季节分解':
    from statsmodels.tsa.seasonal import STL
    # ── 智能列识别：数值列/时间列留空时自动判断 ──
    _time_cands = _auto_time_columns(df)
    _num_cands = _auto_num_columns(df, exclude=_time_cands)
    if not time_column:
        time_column = _time_cands[0] if _time_cands else ''
    if not value_column:
        value_column = _pick_default_numeric(df, _num_cands)
        if value_column is None:
            raise RuntimeError('未找到可用的数值列（请检查数据是否为数值型，或手动指定数值列）')
    _check_col(df, value_column, '数值列')
    if period < 2:
        raise RuntimeError('季节周期 period 必须为 ≥ 2 的整数')
    s, n_miss = _clean_series(df, value_column)
    arr = s.to_numpy()
    n = len(arr)
    if n < 2 * period + 1:
        raise RuntimeError('样本量不足：STL 要求 n > 2×周期（当前 n=' + str(n) + '，周期 P=' + str(period)
                           + '）。请减小周期或提供更长序列')
    sw = None if seasonal_window in (None, 'None', '') else int(seasonal_window)
    tw = None if trend_window in (None, 'None', '') else int(trend_window)
    # statsmodels STL 要求 seasonal/trend/low_pass 均为奇数 ≥3：自动窗口可能算出偶数（如 1.5×12=18），手动补奇数化
    if sw is not None:
        sw = sw if sw % 2 == 1 else sw + 1
    if tw is not None:
        tw = tw if tw % 2 == 1 else tw + 1
    if sw is None:
        sw = int(np.ceil(1.5 * period))
        sw = max(sw, 7)
        sw = sw if sw % 2 == 1 else sw + 1
    if tw is None:
        tw = int(np.ceil(1.5 * period / (1 - 1.5 / sw)))
        tw = max(tw, 3)
        tw = tw if tw % 2 == 1 else tw + 1
    lp = max(period, 7)
    lp = lp if lp % 2 == 1 else lp + 1
    res = STL(arr, period=period, robust=robust, seasonal=sw, trend=tw, low_pass=lp).fit()
    tr, seas, resi = res.trend, res.seasonal, res.resid
    var_res = float(resi.var()) or 1e-12
    Ft = max(0.0, 1.0 - var_res / float((resi + tr).var()))
    Fs = max(0.0, 1.0 - var_res / float((resi + seas).var()))
    season_amp = float(seas.max() - seas.min())
    phase_peak = int(np.argmax(seas) % period)
    phase_trough = int(np.argmin(seas) % period)
    resid_mean = float(resi.mean())
    resid_sd = float(resi.std(ddof=1))
    shapiro_p = float(stats.shapiro(resi).pvalue) if n <= 5000 else None
    x, is_time = _x_axis(df, time_column)
    fig, axes = plt.subplots(4, 1, figsize=(12, 9), sharex=True)
    fig.suptitle('STL 季节分解：{}（周期 P={}）'.format(value_column, period), fontsize=14, fontweight='bold', y=0.998)
    panels = [(arr, NAVY, '观测值 Observed', 1.5), (tr, RED, '趋势 Trend', 2.0),
              (seas, GREEN, '季节 Seasonal', 1.6), (resi, '#888888', '残差 Residual', 1.0)]
    for ax_, (d_, c_, lb_, lw_) in zip(axes, panels):
        ax_.plot(x, d_, color=c_, linewidth=lw_)
        ax_.set_ylabel(lb_, fontsize=9.5, color='#333333')
        _style(ax_)
    axes[2].text(0.985, 0.92, '季节幅度 = {:.4g}'.format(season_amp), transform=axes[2].transAxes,
                 ha='right', va='top', fontsize=9, color='#222222',
                 bbox=dict(facecolor='white', edgecolor='#999999', alpha=0.9, boxstyle='round,pad=0.3'))
    axes[3].text(0.985, 0.92, '残差 SD = {:.4g}'.format(resid_sd), transform=axes[3].transAxes,
                 ha='right', va='top', fontsize=9, color='#222222',
                 bbox=dict(facecolor='white', edgecolor='#999999', alpha=0.9, boxstyle='round,pad=0.3'))
    axes[-1].set_xlabel('时间' if is_time else '序号 t', fontsize=11, color='#333333')
    if is_time:
        plt.setp(axes[-1].get_xticklabels(), rotation=30, ha='right')
    plt.tight_layout(rect=[0, 0, 1, 0.99])
    fs_label = '强季节（Fs>0.64）' if Fs > 0.64 else ('中等季节（0.07<Fs≤0.64）' if Fs > 0.07 else '弱季节（Fs≤0.07）')
    ft_label = '强趋势' if Ft > 0.64 else ('中等趋势' if Ft > 0.07 else '弱趋势')
    report.update({
        '样本量': int(n), '缺失值插值数': int(n_miss), '季节周期P': int(period),
        '列识别_数值列候选': ('、'.join(map(str, _num_cands)) if _num_cands else '未识别到'),
        '列识别_已用数值列': str(value_column),
        '列识别_已用时间列': (str(time_column) if time_column else '（未用，x轴按序号）'),
